=== FILE: apb_gpio.v ===
// apb_gpio: APB4 general-purpose I/O block with interrupts.
// Implements interface_spec.md (sections 1-7) following microarchitecture.md.
// Zero wait states, synchronous active-low reset, single clock (pclk).

module apb_gpio #(
    parameter integer ADDR_WIDTH = 8,
    parameter integer N          = 8
) (
    input  wire                  pclk,
    input  wire                  presetn,
    input  wire [ADDR_WIDTH-1:0] paddr,
    input  wire                  psel,
    input  wire                  penable,
    input  wire                  pwrite,
    input  wire [31:0]           pwdata,
    input  wire [3:0]            pstrb,
    output wire [31:0]           prdata,
    output wire                  pready,
    output wire                  pslverr,
    input  wire [N-1:0]          gpio_in,
    output wire [N-1:0]          gpio_out,
    output wire [N-1:0]          gpio_oe,
    output wire                  irq
);

    // Bits 0 to N-1 set: pins that exist (microarchitecture section 2).
    localparam [31:0] PINS = 32'hFFFF_FFFF >> (32 - N);

    // Register indices, paddr[5:2] (interface spec section 3).
    localparam [3:0] IDX_DATA_OUT    = 4'd0;
    localparam [3:0] IDX_DIR         = 4'd1;
    localparam [3:0] IDX_DATA_IN     = 4'd2;
    localparam [3:0] IDX_INTR_RISE   = 4'd3;
    localparam [3:0] IDX_INTR_FALL   = 4'd4;
    localparam [3:0] IDX_INTR_HIGH   = 4'd5;
    localparam [3:0] IDX_INTR_LOW    = 4'd6;
    localparam [3:0] IDX_INTR_ENABLE = 4'd7;
    localparam [3:0] IDX_INTR_STATUS = 4'd8;

    // ------------------------------------------------------------------
    // APB decode (microarchitecture section 1)
    // ------------------------------------------------------------------
    wire        access     = psel & penable;
    wire [3:0]  index      = paddr[5:2];
    wire        upper_zero = ((paddr >> 6) == {ADDR_WIDTH{1'b0}});
    wire        mapped     = (paddr[1:0] == 2'b00) && upper_zero &&
                             (index <= IDX_INTR_STATUS);
    wire        wr_en      = access & pwrite & mapped;
    wire        rd_en      = access & ~pwrite & mapped;

    // Write mask: byte strobes expanded to bits, limited to existing pins.
    wire [31:0] wmask = {{8{pstrb[3]}}, {8{pstrb[2]}},
                         {8{pstrb[1]}}, {8{pstrb[0]}}} & PINS;
    wire [31:0] wbits = pwdata & wmask;

    // Input widened to 32 bits with zeros above N.
    wire [31:0] in_ext;
    generate
        if (N < 32) begin : g_in_pad
            assign in_ext = {{(32 - N){1'b0}}, gpio_in};
        end else begin : g_in_full
            assign in_ext = gpio_in;
        end
    endgenerate

    // ------------------------------------------------------------------
    // State
    // ------------------------------------------------------------------
    reg [31:0] data_out;
    reg [31:0] dir;
    reg [31:0] intr_rise;
    reg [31:0] intr_fall;
    reg [31:0] intr_high;
    reg [31:0] intr_low;
    reg [31:0] intr_enable;
    reg [31:0] intr_status;
    reg [31:0] in_q;
    reg [31:0] in_prev;

    reg [31:0] data_out_d;
    reg [31:0] dir_d;
    reg [31:0] intr_rise_d;
    reg [31:0] intr_fall_d;
    reg [31:0] intr_high_d;
    reg [31:0] intr_low_d;
    reg [31:0] intr_enable_d;

    // Read/write registers: byte-merged write on the completing cycle.
    always @* begin
        data_out_d    = data_out;
        dir_d         = dir;
        intr_rise_d   = intr_rise;
        intr_fall_d   = intr_fall;
        intr_high_d   = intr_high;
        intr_low_d    = intr_low;
        intr_enable_d = intr_enable;
        if (wr_en) begin
            case (index)
                IDX_DATA_OUT:    data_out_d    = (data_out    & ~wmask) | wbits;
                IDX_DIR:         dir_d         = (dir         & ~wmask) | wbits;
                IDX_INTR_RISE:   intr_rise_d   = (intr_rise   & ~wmask) | wbits;
                IDX_INTR_FALL:   intr_fall_d   = (intr_fall   & ~wmask) | wbits;
                IDX_INTR_HIGH:   intr_high_d   = (intr_high   & ~wmask) | wbits;
                IDX_INTR_LOW:    intr_low_d    = (intr_low    & ~wmask) | wbits;
                IDX_INTR_ENABLE: intr_enable_d = (intr_enable & ~wmask) | wbits;
                default:         data_out_d    = data_out;
            endcase
        end
    end

    // Detection and status (microarchitecture section 3).
    wire [31:0] edge_rise  = in_q & ~in_prev;
    wire [31:0] edge_fall  = ~in_q & in_prev;
    wire [31:0] detected   = ((edge_rise & intr_rise) | (edge_fall & intr_fall) |
                              (in_q & intr_high) | (~in_q & intr_low)) & PINS;
    wire [31:0] clear_bits = (wr_en && (index == IDX_INTR_STATUS)) ? wbits : 32'd0;
    // The OR with detected comes last: a detection beats a clear.
    wire [31:0] status_d   = (intr_status & ~clear_bits) | detected;

    always @(posedge pclk) begin
        if (!presetn) begin
            data_out    <= 32'd0;
            dir         <= 32'd0;
            intr_rise   <= 32'd0;
            intr_fall   <= 32'd0;
            intr_high   <= 32'd0;
            intr_low    <= 32'd0;
            intr_enable <= 32'd0;
            intr_status <= 32'd0;
            in_q        <= 32'd0;
            in_prev     <= 32'd0;
        end else begin
            data_out    <= data_out_d;
            dir         <= dir_d;
            intr_rise   <= intr_rise_d;
            intr_fall   <= intr_fall_d;
            intr_high   <= intr_high_d;
            intr_low    <= intr_low_d;
            intr_enable <= intr_enable_d;
            intr_status <= status_d;
            in_q        <= in_ext;
            in_prev     <= in_q;
        end
    end

    // ------------------------------------------------------------------
    // Read data and response
    // ------------------------------------------------------------------
    reg [31:0] rdata;
    always @* begin
        rdata = 32'd0;
        if (rd_en) begin
            case (index)
                IDX_DATA_OUT:    rdata = data_out;
                IDX_DIR:         rdata = dir;
                IDX_DATA_IN:     rdata = in_q;
                IDX_INTR_RISE:   rdata = intr_rise;
                IDX_INTR_FALL:   rdata = intr_fall;
                IDX_INTR_HIGH:   rdata = intr_high;
                IDX_INTR_LOW:    rdata = intr_low;
                IDX_INTR_ENABLE: rdata = intr_enable;
                IDX_INTR_STATUS: rdata = intr_status;
                default:         rdata = 32'd0;
            endcase
        end
    end

    assign prdata  = rdata;
    assign pready  = 1'b1;
    assign pslverr = access & (~mapped | (pwrite & (index == IDX_DATA_IN)));

    assign gpio_out = data_out[N-1:0];
    assign gpio_oe  = dir[N-1:0];
    assign irq      = |(intr_status & intr_enable);

`ifdef FORMAL
    // Design-intent assertions (not run by any job in this submission).
    always @* begin
        assert (pready);
        if (!access) assert (!pslverr);
        if (!rd_en)  assert (prdata == 32'd0);
    end
`endif

endmodule
=== END FILE ===
=== FILE: apb_gpio_tb.v ===
// apb_gpio_tb: self-checking testbench for apb_gpio at N=8 and N=32.
// Both instances share one APB bus; gpio_in of the N=8 instance is the low
// byte of the N=32 instance's pins. A clocked reference model is compared
// every cycle, and every read is checked against the model and against
// hand-computed values.

module apb_gpio_tb;

    reg         pclk;
    reg         presetn;
    reg         psel;
    reg         penable;
    reg         pwrite;
    reg  [7:0]  paddr;
    reg  [31:0] pwdata;
    reg  [3:0]  pstrb;
    reg  [31:0] gin32;
    wire [7:0]  gin8 = gin32[7:0];

    wire [31:0] prdata8;
    wire [31:0] prdata32;
    wire        pready8;
    wire        pready32;
    wire        pslverr8;
    wire        pslverr32;
    wire [7:0]  gout8;
    wire [7:0]  goe8;
    wire [31:0] gout32;
    wire [31:0] goe32;
    wire        irq8;
    wire        irq32;

    apb_gpio #(.ADDR_WIDTH(8), .N(8)) u_n8 (
        .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel),
        .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
        .prdata(prdata8), .pready(pready8), .pslverr(pslverr8),
        .gpio_in(gin8), .gpio_out(gout8), .gpio_oe(goe8), .irq(irq8)
    );

    apb_gpio #(.ADDR_WIDTH(8), .N(32)) u_n32 (
        .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel),
        .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
        .prdata(prdata32), .pready(pready32), .pslverr(pslverr32),
        .gpio_in(gin32), .gpio_out(gout32), .gpio_oe(goe32), .irq(irq32)
    );

    initial begin
        pclk = 1'b0;
        forever #5 pclk = ~pclk;
    end

    // ------------------------------------------------------------------
    // Reference model (N=32; the N=8 view is the low byte)
    // ------------------------------------------------------------------
    reg [31:0] m_out, m_dir, m_rise, m_fall, m_high, m_low, m_en, m_stat;
    reg [31:0] m_q, m_prev;
    reg [31:0] m_wm, m_det, m_clr;
    reg        m_mapped, m_wr;

    always @* begin
        m_wm     = {{8{pstrb[3]}}, {8{pstrb[2]}}, {8{pstrb[1]}}, {8{pstrb[0]}}};
        m_mapped = (paddr[1:0] == 2'b00) && (paddr <= 8'h20);
        m_wr     = psel && penable && pwrite && m_mapped;
        m_det    = (m_q & ~m_prev & m_rise) | (m_prev & ~m_q & m_fall) |
                   (m_q & m_high) | (~m_q & m_low);
        m_clr    = (m_wr && (paddr == 8'h20)) ? (pwdata & m_wm) : 32'd0;
    end

    always @(posedge pclk) begin
        if (!presetn) begin
            m_out  <= 32'd0; m_dir  <= 32'd0; m_rise <= 32'd0; m_fall <= 32'd0;
            m_high <= 32'd0; m_low  <= 32'd0; m_en   <= 32'd0; m_stat <= 32'd0;
            m_q    <= 32'd0; m_prev <= 32'd0;
        end else begin
            m_q    <= gin32;
            m_prev <= m_q;
            m_stat <= (m_stat & ~m_clr) | m_det;
            if (m_wr) begin
                case (paddr)
                    8'h00: m_out  <= (m_out  & ~m_wm) | (pwdata & m_wm);
                    8'h04: m_dir  <= (m_dir  & ~m_wm) | (pwdata & m_wm);
                    8'h0C: m_rise <= (m_rise & ~m_wm) | (pwdata & m_wm);
                    8'h10: m_fall <= (m_fall & ~m_wm) | (pwdata & m_wm);
                    8'h14: m_high <= (m_high & ~m_wm) | (pwdata & m_wm);
                    8'h18: m_low  <= (m_low  & ~m_wm) | (pwdata & m_wm);
                    8'h1C: m_en   <= (m_en   & ~m_wm) | (pwdata & m_wm);
                    default: m_out <= m_out;
                endcase
            end
        end
    end

    wire m_irq32 = |(m_stat & m_en);
    wire m_irq8  = |(m_stat[7:0] & m_en[7:0]);

    function [31:0] m_read(input [7:0] a);
        begin
            case (a)
                8'h00:   m_read = m_out;
                8'h04:   m_read = m_dir;
                8'h08:   m_read = m_q;
                8'h0C:   m_read = m_rise;
                8'h10:   m_read = m_fall;
                8'h14:   m_read = m_high;
                8'h18:   m_read = m_low;
                8'h1C:   m_read = m_en;
                8'h20:   m_read = m_stat;
                default: m_read = 32'd0;
            endcase
        end
    endfunction

    function m_err(input [7:0] a, input w);
        begin
            m_err = (a[1:0] != 2'b00) || (a > 8'h20) || (w && (a == 8'h08));
        end
    endfunction

    function [7:0] rw_addr(input integer idx);
        begin
            case (idx)
                0:       rw_addr = 8'h00;
                1:       rw_addr = 8'h04;
                2:       rw_addr = 8'h0C;
                3:       rw_addr = 8'h10;
                4:       rw_addr = 8'h14;
                5:       rw_addr = 8'h18;
                6:       rw_addr = 8'h1C;
                default: rw_addr = 8'h00;
            endcase
        end
    endfunction

    // ------------------------------------------------------------------
    // Checking
    // ------------------------------------------------------------------
    integer passed;
    integer failed;
    integer step;
    integer c_pass = 0;
    integer c_fail = 0;
    reg     chk_en;
    reg [31:0] rd32;
    reg [31:0] rd8;
    reg [8*64-1:0] nonce;

    // Every cycle: pins, irq and pready against the model.
    always @(negedge pclk) begin
        if (chk_en) begin
            if ((gout32 === m_out) && (goe32 === m_dir) && (irq32 === m_irq32) &&
                (gout8 === m_out[7:0]) && (goe8 === m_dir[7:0]) && (irq8 === m_irq8) &&
                (pready32 === 1'b1) && (pready8 === 1'b1)) begin
                c_pass = c_pass + 1;
            end else begin
                c_fail = c_fail + 1;
                $error("step %0d: cycle check failed (gpio_out/gpio_oe/irq/pready vs model)", step);
            end
        end
    end

    task chk32(input [31:0] got, input [31:0] exp, input integer code);
        begin
            if (got === exp) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("step %0d check %0d: got %h expected %h", step, code, got, exp);
            end
        end
    endtask

    task chk1(input got, input exp, input integer code);
        begin
            if (got === exp) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("step %0d check %0d: got %b expected %b", step, code, got, exp);
            end
        end
    endtask

    // One APB write; e is the hand-expected pslverr. Optionally changes the
    // pins on the setup negedge (so a detection lands on the completing edge).
    task apb_wr(input [7:0] a, input [31:0] d, input [3:0] s, input e,
                input setp, input [31:0] p);
        begin
            @(negedge pclk);
            paddr = a; pwdata = d; pstrb = s; pwrite = 1'b1;
            psel = 1'b1; penable = 1'b0;
            if (setp) gin32 = p;
            #1;
            chk1(pslverr32, 1'b0, 1);
            chk1(pslverr8, 1'b0, 2);
            chk32(prdata32, 32'd0, 3);
            chk32(prdata8, 32'd0, 4);
            @(negedge pclk);
            penable = 1'b1;
            #1;
            chk1(pready32, 1'b1, 5);
            chk1(pready8, 1'b1, 6);
            chk1(pslverr32, e, 7);
            chk1(pslverr8, e, 8);
            chk1(pslverr32, m_err(a, 1'b1), 9);
            chk32(prdata32, 32'd0, 10);
            chk32(prdata8, 32'd0, 11);
            @(posedge pclk);
            #1;
            psel = 1'b0; penable = 1'b0; pwrite = 1'b0; pstrb = 4'h0;
            chk1(pslverr32, 1'b0, 12);
            chk32(prdata32, 32'd0, 13);
        end
    endtask

    task wr(input [7:0] a, input [31:0] d, input [3:0] s, input e);
        begin
            apb_wr(a, d, s, e, 1'b0, 32'd0);
        end
    endtask

    task wrp(input [7:0] a, input [31:0] d, input [3:0] s, input e, input [31:0] p);
        begin
            apb_wr(a, d, s, e, 1'b1, p);
        end
    endtask

    // One APB read; checks against the model and captures rd32 and rd8.
    task apb_read(input [7:0] a, input e);
        reg [31:0] mexp;
        begin
            @(negedge pclk);
            paddr = a; pwdata = 32'd0; pstrb = 4'h0; pwrite = 1'b0;
            psel = 1'b1; penable = 1'b0;
            #1;
            chk1(pslverr32, 1'b0, 14);
            chk1(pslverr8, 1'b0, 15);
            chk32(prdata32, 32'd0, 16);
            chk32(prdata8, 32'd0, 17);
            @(negedge pclk);
            penable = 1'b1;
            #1;
            mexp = m_read(a);
            chk1(pready32, 1'b1, 18);
            chk1(pready8, 1'b1, 19);
            chk1(pslverr32, e, 20);
            chk1(pslverr8, e, 21);
            chk1(pslverr32, m_err(a, 1'b0), 22);
            chk32(prdata32, mexp, 23);
            chk32(prdata8, mexp & 32'h0000_00FF, 24);
            rd32 = prdata32;
            rd8  = prdata8;
            @(posedge pclk);
            #1;
            psel = 1'b0; penable = 1'b0;
            chk1(pslverr32, 1'b0, 25);
            chk32(prdata32, 32'd0, 26);
        end
    endtask

    // Read with hand-computed expectations for N=32 and N=8.
    task rd(input [7:0] a, input e, input [31:0] x32, input [31:0] x8);
        begin
            apb_read(a, e);
            chk32(rd32, x32, 27);
            chk32(rd8, x8, 28);
        end
    endtask

    task set_pins(input [31:0] v);
        begin
            @(negedge pclk);
            gin32 = v;
        end
    endtask

    task idle(input integer n);
        begin
            repeat (n) @(posedge pclk);
            #1;
        end
    endtask

    task chk_outputs_zero;
        begin
            chk32(gout32, 32'd0, 40);
            chk32(goe32, 32'd0, 41);
            chk32({24'd0, gout8}, 32'd0, 42);
            chk32({24'd0, goe8}, 32'd0, 43);
            chk1(irq32, 1'b0, 44);
            chk1(irq8, 1'b0, 45);
        end
    endtask

    integer i;

    initial begin
        passed = 0; failed = 0; step = 0; chk_en = 1'b0;
        presetn = 1'b0; psel = 1'b0; penable = 1'b0; pwrite = 1'b0;
        paddr = 8'h00; pwdata = 32'd0; pstrb = 4'h0; gin32 = 32'd0;
        rd32 = 32'd0; rd8 = 32'd0;

        // ---- Reset ----
        repeat (3) @(posedge pclk);
        #1;
        chk_en = 1'b1;
        chk_outputs_zero;
        @(negedge pclk);
        presetn = 1'b1;

        // ---- Step 1: reset values ----
        step = 1;
        rd(8'h00, 1'b0, 32'd0, 32'd0);
        rd(8'h04, 1'b0, 32'd0, 32'd0);
        rd(8'h08, 1'b0, 32'd0, 32'd0);
        rd(8'h0C, 1'b0, 32'd0, 32'd0);
        rd(8'h10, 1'b0, 32'd0, 32'd0);
        rd(8'h14, 1'b0, 32'd0, 32'd0);
        rd(8'h18, 1'b0, 32'd0, 32'd0);
        rd(8'h1C, 1'b0, 32'd0, 32'd0);
        rd(8'h20, 1'b0, 32'd0, 32'd0);

        // ---- Step 2: read/write registers, partial strobes, bits above N ----
        step = 2;
        for (i = 0; i < 7; i = i + 1) begin
            wr(rw_addr(i), 32'hFFFF_FFFF, 4'hF, 1'b0);
            rd(rw_addr(i), 1'b0, 32'hFFFF_FFFF, 32'h0000_00FF);
            wr(rw_addr(i), 32'h1234_5678, 4'b0101, 1'b0);
            rd(rw_addr(i), 1'b0, 32'hFF34_FF78, 32'h0000_0078);
            wr(rw_addr(i), 32'hA5A5_A5A5, 4'b1010, 1'b0);
            rd(rw_addr(i), 1'b0, 32'hA534_A578, 32'h0000_0078);
            wr(rw_addr(i), 32'h0000_0000, 4'b0000, 1'b0);
            rd(rw_addr(i), 1'b0, 32'hA534_A578, 32'h0000_0078);
            wr(rw_addr(i), 32'h0000_0000, 4'hF, 1'b0);
            rd(rw_addr(i), 1'b0, 32'd0, 32'd0);
        end
        // INTR_LOW set status bits above; clear them all now.
        wr(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
        rd(8'h20, 1'b0, 32'd0, 32'd0);
        chk1(irq32, 1'b0, 50);
        chk1(irq8, 1'b0, 51);

        // ---- Step 3: gpio_out and gpio_oe ----
        step = 3;
        wr(8'h00, 32'hA5C3_0F96, 4'hF, 1'b0);
        wr(8'h04, 32'h5A3C_F069, 4'hF, 1'b0);
        chk32(gout32, 32'hA5C3_0F96, 52);
        chk32({24'd0, gout8}, 32'h0000_0096, 53);
        chk32(goe32, 32'h5A3C_F069, 54);
        chk32({24'd0, goe8}, 32'h0000_0069, 55);
        rd(8'h00, 1'b0, 32'hA5C3_0F96, 32'h0000_0096);
        rd(8'h04, 1'b0, 32'h5A3C_F069, 32'h0000_0069);

        // ---- Step 4: DATA_IN, read only ----
        step = 4;
        set_pins(32'hDEAD_BEEF);
        rd(8'h08, 1'b0, 32'hDEAD_BEEF, 32'h0000_00EF);
        wr(8'h08, 32'h1234_5678, 4'hF, 1'b1);
        rd(8'h08, 1'b0, 32'hDEAD_BEEF, 32'h0000_00EF);
        rd(8'h00, 1'b0, 32'hA5C3_0F96, 32'h0000_0096);
        set_pins(32'd0);
        rd(8'h08, 1'b0, 32'd0, 32'd0);

        // ---- Step 5: PSLVERR policy, unmapped and aliasing addresses ----
        step = 5;
        wr(8'h24, 32'hFFFF_FFFF, 4'hF, 1'b1);
        wr(8'h01, 32'hFFFF_FFFF, 4'hF, 1'b1);
        wr(8'h02, 32'hFFFF_FFFF, 4'hF, 1'b1);
        wr(8'h03, 32'hFFFF_FFFF, 4'hF, 1'b1);
        wr(8'h21, 32'hFFFF_FFFF, 4'hF, 1'b1);
        wr(8'h40, 32'hFFFF_FFFF, 4'hF, 1'b1);
        wr(8'h41, 32'hFFFF_FFFF, 4'hF, 1'b1);
        wr(8'h44, 32'hFFFF_FFFF, 4'hF, 1'b1);
        wr(8'h4C, 32'hFFFF_FFFF, 4'hF, 1'b1);
        wr(8'h5C, 32'hFFFF_FFFF, 4'hF, 1'b1);
        wr(8'h60, 32'hFFFF_FFFF, 4'hF, 1'b1);
        wr(8'h80, 32'hFFFF_FFFF, 4'hF, 1'b1);
        wr(8'hFC, 32'hFFFF_FFFF, 4'hF, 1'b1);
        rd(8'h00, 1'b0, 32'hA5C3_0F96, 32'h0000_0096);
        rd(8'h04, 1'b0, 32'h5A3C_F069, 32'h0000_0069);
        rd(8'h0C, 1'b0, 32'd0, 32'd0);
        rd(8'h14, 1'b0, 32'd0, 32'd0);
        rd(8'h1C, 1'b0, 32'd0, 32'd0);
        rd(8'h20, 1'b0, 32'd0, 32'd0);
        rd(8'h24, 1'b1, 32'd0, 32'd0);
        rd(8'h28, 1'b1, 32'd0, 32'd0);
        rd(8'h3C, 1'b1, 32'd0, 32'd0);
        rd(8'h40, 1'b1, 32'd0, 32'd0);
        rd(8'h44, 1'b1, 32'd0, 32'd0);
        rd(8'h60, 1'b1, 32'd0, 32'd0);
        rd(8'h80, 1'b1, 32'd0, 32'd0);
        rd(8'hFF, 1'b1, 32'd0, 32'd0);
        rd(8'h01, 1'b1, 32'd0, 32'd0);
        rd(8'h05, 1'b1, 32'd0, 32'd0);
        rd(8'h22, 1'b1, 32'd0, 32'd0);
        rd(8'h23, 1'b1, 32'd0, 32'd0);

        // ---- Step 6: rising edge fires once ----
        step = 6;
        wr(8'h0C, 32'h0000_0001, 4'hF, 1'b0);
        set_pins(32'h0000_0001);
        idle(2);
        rd(8'h20, 1'b0, 32'h0000_0001, 32'h0000_0001);
        wr(8'h20, 32'h0000_0001, 4'hF, 1'b0);
        rd(8'h20, 1'b0, 32'd0, 32'd0);
        idle(3);
        rd(8'h20, 1'b0, 32'd0, 32'd0);

        // ---- Step 7: falling edge ----
        step = 7;
        wr(8'h10, 32'h0000_0004, 4'hF, 1'b0);
        set_pins(32'h0000_0005);
        idle(3);
        rd(8'h20, 1'b0, 32'd0, 32'd0);
        set_pins(32'h0000_0001);
        idle(2);
        rd(8'h20, 1'b0, 32'h0000_0004, 32'h0000_0004);
        wr(8'h20, 32'h0000_0004, 4'hF, 1'b0);
        rd(8'h20, 1'b0, 32'd0, 32'd0);
        wr(8'h10, 32'd0, 4'hF, 1'b0);

        // ---- Step 8: high level sets again after a clear ----
        step = 8;
        wr(8'h14, 32'h0000_0008, 4'hF, 1'b0);
        set_pins(32'h0000_0009);
        idle(2);
        rd(8'h20, 1'b0, 32'h0000_0008, 32'h0000_0008);
        wr(8'h20, 32'h0000_0008, 4'hF, 1'b0);
        rd(8'h20, 1'b0, 32'h0000_0008, 32'h0000_0008);
        set_pins(32'h0000_0001);
        idle(2);
        wr(8'h20, 32'h0000_0008, 4'hF, 1'b0);
        rd(8'h20, 1'b0, 32'd0, 32'd0);
        wr(8'h14, 32'd0, 4'hF, 1'b0);

        // ---- Step 9: low level ----
        step = 9;
        wr(8'h18, 32'h0000_0010, 4'hF, 1'b0);
        rd(8'h20, 1'b0, 32'h0000_0010, 32'h0000_0010);
        wr(8'h20, 32'h0000_0010, 4'hF, 1'b0);
        rd(8'h20, 1'b0, 32'h0000_0010, 32'h0000_0010);
        set_pins(32'h0000_0011);
        idle(2);
        wr(8'h20, 32'h0000_0010, 4'hF, 1'b0);
        rd(8'h20, 1'b0, 32'd0, 32'd0);
        wr(8'h18, 32'd0, 4'hF, 1'b0);

        // ---- Step 10: both edges on pin 5, and a one-cycle pulse ----
        step = 10;
        wr(8'h0C, 32'h0000_0021, 4'hF, 1'b0);
        wr(8'h10, 32'h0000_0020, 4'hF, 1'b0);
        set_pins(32'h0000_0031);
        idle(2);
        rd(8'h20, 1'b0, 32'h0000_0020, 32'h0000_0020);
        wr(8'h20, 32'h0000_0020, 4'hF, 1'b0);
        rd(8'h20, 1'b0, 32'd0, 32'd0);
        set_pins(32'h0000_0011);
        idle(2);
        rd(8'h20, 1'b0, 32'h0000_0020, 32'h0000_0020);
        wr(8'h20, 32'h0000_0020, 4'hF, 1'b0);
        rd(8'h20, 1'b0, 32'd0, 32'd0);
        set_pins(32'h0000_0031);
        set_pins(32'h0000_0011);
        idle(3);
        rd(8'h20, 1'b0, 32'h0000_0020, 32'h0000_0020);
        wr(8'h20, 32'h0000_0020, 4'hF, 1'b0);
        rd(8'h20, 1'b0, 32'd0, 32'd0);
        wr(8'h10, 32'd0, 4'hF, 1'b0);

        // ---- Step 11: several pending, partial clears, interrupt mask ----
        step = 11;
        wr(8'h0C, 32'h0001_00C1, 4'hF, 1'b0);
        set_pins(32'h0001_00D1);
        idle(2);
        rd(8'h20, 1'b0, 32'h0001_00C0, 32'h0000_00C0);
        chk1(irq32, 1'b0, 60);
        chk1(irq8, 1'b0, 61);
        wr(8'h1C, 32'h0001_0000, 4'hF, 1'b0);
        chk1(irq32, 1'b1, 62);
        chk1(irq8, 1'b0, 63);
        wr(8'h1C, 32'h0001_0040, 4'hF, 1'b0);
        chk1(irq32, 1'b1, 64);
        chk1(irq8, 1'b1, 65);
        wr(8'h20, 32'h0000_0040, 4'hF, 1'b0);
        rd(8'h20, 1'b0, 32'h0001_0080, 32'h0000_0080);
        chk1(irq32, 1'b1, 66);
        chk1(irq8, 1'b0, 67);
        wr(8'h20, 32'h0001_0080, 4'b0001, 1'b0);
        rd(8'h20, 1'b0, 32'h0001_0000, 32'h0000_0000);
        chk1(irq32, 1'b1, 68);
        wr(8'h20, 32'h0001_0000, 4'b0100, 1'b0);
        rd(8'h20, 1'b0, 32'd0, 32'd0);
        chk1(irq32, 1'b0, 69);
        chk1(irq8, 1'b0, 70);
        wr(8'h1C, 32'd0, 4'hF, 1'b0);

        // ---- Step 12: a detection beats a clear on the same edge ----
        step = 12;
        set_pins(32'h0001_00D0);
        idle(2);
        set_pins(32'h0001_00D1);
        idle(2);
        rd(8'h20, 1'b0, 32'h0000_0001, 32'h0000_0001);
        set_pins(32'h0001_00D0);
        idle(2);
        rd(8'h20, 1'b0, 32'h0000_0001, 32'h0000_0001);
        wrp(8'h20, 32'h0000_0001, 4'hF, 1'b0, 32'h0001_00D1);
        rd(8'h20, 1'b0, 32'h0000_0001, 32'h0000_0001);
        wr(8'h20, 32'h0000_0001, 4'hF, 1'b0);
        rd(8'h20, 1'b0, 32'd0, 32'd0);
        wr(8'h0C, 32'd0, 4'hF, 1'b0);

        // ---- Step 13: reset again ----
        step = 13;
        wr(8'h00, 32'hFFFF_FFFF, 4'hF, 1'b0);
        wr(8'h04, 32'hFFFF_FFFF, 4'hF, 1'b0);
        wr(8'h1C, 32'hFFFF_FFFF, 4'hF, 1'b0);
        wr(8'h18, 32'hFFFF_FFFF, 4'hF, 1'b0);
        idle(2);
        chk1(irq32, 1'b1, 71);
        chk1(irq8, 1'b1, 72);
        @(negedge pclk);
        presetn = 1'b0;
        @(posedge pclk);
        #1;
        chk_outputs_zero;
        @(posedge pclk);
        #1;
        chk_outputs_zero;
        @(negedge pclk);
        presetn = 1'b1;
        rd(8'h00, 1'b0, 32'd0, 32'd0);
        rd(8'h04, 1'b0, 32'd0, 32'd0);
        rd(8'h08, 1'b0, 32'h0001_00D1, 32'h0000_00D1);
        rd(8'h0C, 1'b0, 32'd0, 32'd0);
        rd(8'h10, 1'b0, 32'd0, 32'd0);
        rd(8'h14, 1'b0, 32'd0, 32'd0);
        rd(8'h18, 1'b0, 32'd0, 32'd0);
        rd(8'h1C, 1'b0, 32'd0, 32'd0);
        rd(8'h20, 1'b0, 32'd0, 32'd0);
        chk_outputs_zero;
        idle(2);

        // ---- Verdict ----
        passed = passed + c_pass;
        failed = failed + c_fail;
        if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) nonce = {(8*64){1'b0}};
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

